-- Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- ============================================
-- 1. TUGAS (renamed from tasks)
-- ============================================
CREATE TABLE IF NOT EXISTS public.tugas (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,
    nama TEXT NOT NULL,
    tanggal DATE NOT NULL,
    estimasi_menit INT DEFAULT 0,
    prioritas TEXT CHECK (prioritas IN ('p1', 'p2', 'p3', 'p4')) DEFAULT 'p3',
    status TEXT CHECK (status IN ('proses', 'belum', 'selesai')) DEFAULT 'belum',
    started_at TIMESTAMPTZ NULL,
    completed_at TIMESTAMPTZ NULL,
    accumulated_seconds INT NOT NULL DEFAULT 0,
    is_paused BOOLEAN NOT NULL DEFAULT FALSE,
    last_resumed_at TIMESTAMPTZ NULL,
    group_id UUID,
    group_order INTEGER,
    terlewat_tanggal DATE DEFAULT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_tugas_user_date ON public.tugas(user_id, tanggal);
CREATE INDEX IF NOT EXISTS idx_tugas_user_status ON public.tugas(user_id, status);
CREATE INDEX IF NOT EXISTS idx_tugas_user_priority ON public.tugas(user_id, prioritas);
CREATE INDEX IF NOT EXISTS idx_tugas_user_created_at ON public.tugas(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tugas_group_id ON public.tugas(group_id);

ALTER TABLE public.tugas ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users can CRUD own tugas" ON public.tugas;
CREATE POLICY "Users can CRUD own tugas" ON public.tugas
    FOR ALL USING (auth.uid() = user_id);

