    sholat_maghrib BOOLEAN DEFAULT FALSE,
    sholat_isya BOOLEAN DEFAULT FALSE,
    alasan_subuh TEXT,
    alasan_dhuha TEXT,
    alasan_dzuhur TEXT,
    alasan_ashar TEXT,
    alasan_maghrib TEXT,
    alasan_isya TEXT,
    kualitas_subuh SMALLINT DEFAULT NULL CHECK (kualitas_subuh IN (1, 2, 3, 4, 5)),
    kualitas_dhuha SMALLINT DEFAULT NULL CHECK (kualitas_dhuha IN (1, 2, 3, 4, 5)),
    kualitas_dzuhur SMALLINT DEFAULT NULL CHECK (kualitas_dzuhur IN (1, 2, 3, 4, 5)),
    kualitas_ashar SMALLINT DEFAULT NULL CHECK (kualitas_ashar IN (1, 2, 3, 4, 5)),
    kualitas_maghrib SMALLINT DEFAULT NULL CHECK (kualitas_maghrib IN (1, 2, 3, 4, 5)),
    kualitas_isya SMALLINT DEFAULT NULL CHECK (kualitas_isya IN (1, 2, 3, 4, 5)),
